import { Component, EventEmitter, Input, Output, signal, OnInit, OnChanges, SimpleChanges } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ReminderService } from '../../../services/reminder.service';
import { TranslationService } from '../../../services/translation.service';
import { Reminder, UpdateReminderRequest } from '../../../models/reminder.model';

@Component({
  selector: 'app-edit-reminder-modal',
  standalone: false,
  templateUrl: './edit-reminder-modal.component.html',
  styleUrls: ['./edit-reminder-modal.component.css']
})
export class EditReminderModalComponent implements OnInit, OnChanges {
  @Input() isOpen = signal(false);
  @Input() reminder: Reminder | null = null;
  @Output() reminderUpdated = new EventEmitter<void>();
  @Output() closeModal = new EventEmitter<void>();

  reminderForm: FormGroup;
  loading = signal(false);
  error = signal<string | null>(null);

  constructor(
    private fb: FormBuilder,
    private reminderService: ReminderService,
    private translationService: TranslationService
  ) {
    this.reminderForm = this.fb.group({
      title: ['', [Validators.required, Validators.minLength(3)]],
      description: [''],
      eventTime: ['', Validators.required],
      reminderTime: ['', Validators.required]
    });
  }

  ngOnInit(): void {
    this.initializeForm();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['reminder'] && this.reminder) {
      this.initializeForm();
    }
  }

  private initializeForm(): void {
    if (this.reminder) {
      // Format for datetime-local input directly from string
      const eventTimeFormatted = this.formatDateTimeForInput(this.reminder.eventTime);
      const reminderTimeFormatted = this.formatDateTimeForInput(this.reminder.reminderTime);

      this.reminderForm.patchValue({
        title: this.reminder.title,
        description: this.reminder.description,
        eventTime: eventTimeFormatted,
        reminderTime: reminderTimeFormatted
      });
    }
  }

  private formatDateTimeForInput(dateString: string): string {
    // Create a new Date object from the string (handles UTC automatically)
    const date = new Date(dateString);
    
    // Get local timezone values
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  }

  onSubmit(): void {
    if (this.reminderForm.valid && this.reminder) {
      // Check if dates are in the past
      const now = new Date();
      const eventTime = new Date(this.reminderForm.value.eventTime);
      const reminderTime = new Date(this.reminderForm.value.reminderTime);
      
      if (eventTime < now || reminderTime < now) {
        this.error.set(this.translate('reminders.past_date_error'));
        return;
      }
      
      // Check if reminder time is before event time
      if (reminderTime >= eventTime) {
        this.error.set(this.translate('reminders.validation_error'));
        return;
      }
      
      this.loading.set(true);
      this.error.set(null);

      const formValue = this.reminderForm.value;
      const reminderData: UpdateReminderRequest = {
        id: this.reminder.id,
        title: formValue.title,
        description: formValue.description,
        eventTime: new Date(formValue.eventTime).toISOString(),
        reminderTime: new Date(formValue.reminderTime).toISOString()
      };

      this.reminderService.updateReminder(reminderData).subscribe({
        next: (response) => {
          this.loading.set(false);
          if (response.success) {
            this.reminderUpdated.emit();
            this.closeModal.emit();
          } else {
            // Handle specific error messages from server
            let errorMessage = response.message;
            
            // If server message is already in Arabic, use it directly
            if (response.message) {
              errorMessage = response.message;
            } else {
              errorMessage = this.translate('reminders.update_error');
            }
            
            this.error.set(errorMessage);
          }
        },
        error: (error) => {
          this.loading.set(false);
          console.error('Error updating reminder:', error);
          
          // Extract error message from HTTP error response
          let errorMessage = this.translate('reminders.update_error');
          
          if (error.error && error.error.message) {
            errorMessage = error.error.message;
          } else if (error.message) {
            errorMessage = error.message;
          }
          
          this.error.set(errorMessage);
        }
      });
    } else {
      this.markFormGroupTouched();
    }
  }

  onCancel(): void {
    this.closeModal.emit();
  }

  private markFormGroupTouched(): void {
    Object.keys(this.reminderForm.controls).forEach(key => {
      const control = this.reminderForm.get(key);
      control?.markAsTouched();
    });
  }

  translate(key: string): string {
    return this.translationService.translate(key);
  }

  getFieldError(fieldName: string): string {
    const field = this.reminderForm.get(fieldName);
    if (field?.errors && field.touched) {
      if (field.errors['required']) {
        return this.translate('field_required');
      }
      if (field.errors['minlength']) {
        return `${this.translate('min_length')} ${field.errors['minlength'].requiredLength}`;
      }
    }
    return '';
  }
}
